package com.nook.widgets;

import java.util.*;
import org.json.JSONObject;

/** Explicit stock-family coverage and named layouts, rather than a brand filter over the same tool list. */
public final class StockCatalog {
    private StockCatalog(){}
    public record Family(String brand,String key,String title,String kind,String source,String detail,JSONObject options){}
    public record Preset(String id,Family family,String layout,int variant,String size,int width,int height,int clockFace){}
    private static final List<Family> FAMILIES=new ArrayList<>();
    private static final List<Preset> PRESETS=new ArrayList<>();
    private static JSONObject options(String... pairs){JSONObject result=new JSONObject();for(int n=0;n+1<pairs.length;n+=2)ExtraData.put(result,pairs[n],pairs[n+1]);return result;}
    private static void add(String brand,String key,String title,String kind,String source,String detail,JSONObject options){FAMILIES.add(new Family(brand,key,title,kind,source,detail,options));}
    private static void tool(String brand,String key,String title,String kind){String source=switch(kind){case "weather"->"Connected city · Open-Meteo";case "music"->"Active Android player";case "screentime"->"Optional Android usage access";case "files"->"Chosen documents";case "photos"->"Chosen image";case "translate","maps"->"External provider shortcut";default->"Android / Nook data";};String detail=kind.equals("weather")?"Open-Meteo conditions and forecast for the city you choose; no device-location access.":Widgets.description(kind);add(brand,key,title,kind,source,detail,options("title",title));}
    private static void manual(String brand,String key,String title,String type,String unit){JSONObject opts=options("title",title,"trackerName",title,"trackerType",type,"unit",unit);ExtraData.put(opts,"daily",!type.equals("reading")&&!type.equals("sleep"));add(brand,key,title,"tracker","Manual log","Your own entries; no private health account or automatic sensor history is supplied.",opts);}
    private static void service(String brand,String key,String title,String detail){add(brand,key,title,"service","Manual / app shortcut",detail,options("title",title,"serviceName",title));}
    static {
        for(String brand:new String[]{"Apple","macOS","Pixel","Samsung","Nothing"}){
            tool(brand,"clock","Clock","clock");tool(brand,"worldclock","World clock","worldclock");tool(brand,"weather","Weather","weather");tool(brand,"photos","Photos","photos");tool(brand,"music","Music","music");tool(brand,"battery","Batteries","battery");tool(brand,"calendar","Calendar","calendar");tool(brand,"agenda","Up next","agenda");tool(brand,"notes","Notes","notes");tool(brand,"reminders","Reminders","reminders");tool(brand,"countdown","Countdown","countdown");
        }
        for(String brand:new String[]{"Apple","macOS"}){
            tool(brand,"contacts","Contacts","contacts");tool(brand,"files","Files","files");tool(brand,"shortcuts","Shortcuts","shortcuts");tool(brand,"safari","Safari reading list","bookmarks");tool(brand,"maps","Maps · saved places","maps");tool(brand,"podcasts","Podcasts · active player","music");tool(brand,"screentime","Screen Time","screentime");tool(brand,"tips","Tips","tips");tool(brand,"journal","Journal · your notes","notes");
            add(brand,"news","News · your feed","news","Connected RSS source","Headlines from your selected feed; no Apple News account.",options("title","News"));add(brand,"stocks","Stocks","stocks","Connected market provider","Your provider's quotes and trading date; requires your Alpha Vantage key.",options("title","Stocks"));
            manual(brand,"fitness","Fitness rings","activity","");manual(brand,"steps","Health · steps log","steps","steps");manual(brand,"sleep","Sleep record","sleep","minutes");manual(brand,"medications","Medication check-in","medications","check-ins");manual(brand,"books","Books · reading progress","reading","pages");
            service(brand,"mail","Mail","Manual card or shortcut to your installed mail app. iCloud inbox data is not connected.");service(brand,"home","Home","Manual card or shortcut to your smart-home app. HomeKit devices and scenes are not connected.");service(brand,"findmy","Find My","Shortcut to a device-finding app you choose. Apple people, items and device locations are not supplied.");service(brand,"wallet","Wallet","Manual card or shortcut to your wallet app. Cards, balances, passes and payment credentials are not read.");service(brand,"tv","TV","Shortcut to your video app. Apple viewing history and subscriptions are not connected.");service(brand,"gamecenter","Game Center","Manual card or game-app shortcut. Apple achievements and friends are not connected.");service(brand,"appstore","App Store","Shortcut to your app store. Apple editorial content and account history are not connected.");
        }
        for(String brand:new String[]{"Samsung","Pixel"}){tool(brand,"contacts","Contacts","contacts");tool(brand,"screen","Digital Wellbeing","screentime");tool(brand,"shortcuts","App shortcuts","shortcuts");tool(brand,"maps","Maps · destinations","maps");tool(brand,"files",brand.equals("Pixel")?"Drive · chosen files":"My Files · chosen files","files");tool(brand,"bookmarks",brand.equals("Pixel")?"Chrome · bookmarks":"Internet · bookmarks","bookmarks");tool(brand,"search","Search","search");tool(brand,"controls","Settings shortcuts","controls");tool(brand,"recorder","Voice Recorder","recorder");tool(brand,"tasks","Tasks","checklist");add(brand,"news","News · your feed","news","Connected RSS source","Read your chosen source; no vendor news account.",options("title","News"));}
        tool("Samsung","devicecare","Device care","devicecare");manual("Samsung","activity","Samsung Health · activity log","activity","");manual("Samsung","steps","Samsung Health · steps log","steps","steps");manual("Samsung","sleep","Samsung Health · sleep log","sleep","minutes");manual("Samsung","water","Samsung Health · water log","water","ml");manual("Samsung","medications","Samsung Health · check-ins","medications","check-ins");service("Samsung","smartthings","SmartThings","Manual card or installed-app shortcut. Samsung cloud devices and scenes are not connected.");service("Samsung","modes","Modes and Routines","Shortcut to your chosen automation app. Nook does not claim to execute Samsung's private routines.");service("Samsung","buds","Galaxy Buds","Shortcut to your wearable app. Private accessory battery readings and device controls are not supplied.");service("Samsung","email","Samsung Email","Shortcut to your installed email app; private inbox data is not connected.");service("Samsung","suggestions","Smart suggestions","Your chosen app shortcuts; no proprietary recommendation engine.");
        tool("Pixel","translate","Translate","translate");tool("Pixel","keep","Keep · checklist","checklist");tool("Pixel","youtube","YouTube Music · active player","music");service("Pixel","home","Google Home","Manual card or installed-app shortcut; Google Home devices and actions are not connected.");service("Pixel","gmail","Gmail","Shortcut to your installed mail app; Gmail inbox data is not connected.");service("Pixel","gemini","Gemini","Shortcut to your chosen assistant app; no assistant account or conversation data is read.");
        tool("Nothing","compass","Compass","compass");tool("Nothing","recorder","Recorder","recorder");tool("Nothing","screen","Screen time","screentime");tool("Nothing","controls","Quick settings","controls");tool("Nothing","stopwatch","Stopwatch","stopwatch");tool("Nothing","breathing","Breathing","breathing");manual("Nothing","steps","Pedometer · manual log","steps","steps");
        for(String brand:new String[]{"Nothing","Pixel"}){JSONObject quick=options("title",brand.equals("Nothing")?"Quick Look":"At a Glance");ExtraData.put(quick,"quickLook",true);add(brand,"quicklook",brand.equals("Nothing")?"Quick Look":"At a Glance","clock","Android / connected city","Native time, optional visible-calendar event and your selected city's weather.",quick);}
        for(Family f:FAMILIES){String[][] layouts=layouts(f);for(int n=0;n<layouts.length;n++)for(String size:new String[]{"Small","Medium","Large"}){int w=size.equals("Small")?180:320,h=size.equals("Large")?320:180;String[] layout=layouts[n];int variant=Integer.parseInt(layout[1]),face=Integer.parseInt(layout[2]);if(size.equals("Small")&&(f.kind().equals("weather")&&variant==1||f.kind().equals("calendar")&&variant==0||f.kind().equals("worldclock")&&variant==0))continue;PRESETS.add(new Preset(f.brand()+"/"+f.key()+"/"+n+"/"+size,f,layout[0],variant,size,w,h,face));}}
    }
    private static String[][] layouts(Family f){return switch(f.kind()){case "clock"->f.options().optBoolean("quickLook",false)?new String[][]{{"Time, event and weather","0","1"}}:new String[][]{{"Analog face","0","2"},{"Digital · 12 hour","0","1"},{"Digital · 24 hour","1","1"},{"Stacked digits","0","3"}};case "weather"->new String[][]{{"Current conditions","0","0"},{"Three-day forecast","1","0"}};case "calendar"->new String[][]{{"Month","0","0"},{"Week","1","0"}};case "notes"->new String[][]{{"One note","0","0"},{"Notes list","1","0"}};case "photos"->new String[][]{{"Fill frame","0","0"},{"Fit whole photo","1","0"}};case "battery"->new String[][]{{"Battery ring","0","0"},{"Large percentage","1","0"}};case "worldclock"->new String[][]{{"Three cities","0","0"},{"One city","1","0"}};case "contacts"->new String[][]{{"Three favorites","0","0"},{"One favorite","1","0"}};case "breathing"->new String[][]{{"Box rhythm","0","0"},{"4–7–8 rhythm","1","0"},{"Steady rhythm","2","0"}};case "reminders"->new String[][]{{"All upcoming","0","0"},{"Due today and overdue","1","0"}};case "checklist"->new String[][]{{"Unfinished tasks","0","0"},{"All tasks","1","0"}};case "agenda","countdown","search","controls","music"->namedLayouts(LibraryWidgets.variants(f.kind()));default->new String[][]{{"Detailed","0","0"},{"Summary","1","0"}};};}
    private static String[][] namedLayouts(String[] labels){String[][] result=new String[labels.length][3];for(int n=0;n<labels.length;n++)result[n]=new String[]{labels[n],String.valueOf(n),"0"};return result;}
    public static int design(String brand){return switch(brand){case "Apple"->2;case "macOS"->3;case "Samsung"->7;case "Nothing"->1;case "Pixel"->4;default->0;};}
    public static List<Family> families(String brand){List<Family> result=new ArrayList<>();for(Family f:FAMILIES)if(f.brand().equals(brand))result.add(f);return result;}
    public static List<Preset> presets(Family family){List<Preset> result=new ArrayList<>();for(Preset p:PRESETS)if(p.family()==family)result.add(p);return result;}
    public static List<Preset> all(){return Collections.unmodifiableList(PRESETS);}
    public static Preset find(String id){for(Preset p:PRESETS)if(p.id().equals(id))return p;return null;}
    public static JSONObject configuration(Preset p){JSONObject config=Widgets.defaults(p.family().kind());WidgetDesign.select(config,design(p.family().brand()));try{JSONObject options=p.family().options();for(Iterator<String> keys=options.keys();keys.hasNext();){String key=keys.next();config.put(key,options.get(key));}config.put("variant",p.variant()).put("clockFace",p.clockFace()).put("preferredWidth",p.width()).put("preferredHeight",p.height()).put("density",p.size().equals("Small")?1:0).put("stockPreset",p.id());}catch(Exception e){throw new IllegalStateException(e);}return config;}
}
